<script setup lang="ts">
import {ref,onMounted} from 'vue'
import AssuranceContactEditor from './AssuranceContactEditor.vue'
const props=defineProps<{request:(path:string,body?:any,method?:string)=>Promise<any>;portal:(path:string,body?:any)=>Promise<any>}>()
const rows=ref<any[]>([]),page=ref(1),count=ref(0),busy=ref(false),error=ref(''),selected=ref<any>(null)
const filters=ref({search:'',kind:'',status:'',starts_from:'',starts_to:'',ends_from:'',ends_to:''})
const states:Record<string,string>={draft:'Brouillon',tracking:'En suivi',archived:'Archivé'}
let lastRequest=0
async function load(reset=false){if(reset)page.value=1;const current=++lastRequest;busy.value=true;error.value='';rows.value=[];try{const query=new URLSearchParams({page:String(page.value)});for(const [key,value] of Object.entries(filters.value))if(value)query.set(key,value);const result=await props.request(`agreement-registry/?${query}`);if(current!==lastRequest)return;rows.value=result.results;count.value=result.count}catch(e:any){if(current===lastRequest){error.value=e.message;count.value=0}}finally{if(current===lastRequest)busy.value=false}}
async function open(row:any){busy.value=true;error.value='';try{selected.value=await props.request(`contacts/${row.contact.id}/`)}catch(e:any){error.value=e.message}finally{busy.value=false}}
function clear(){filters.value={search:'',kind:'',status:'',starts_from:'',starts_to:'',ends_from:'',ends_to:''};void load(true)}
onMounted(()=>load())
</script>
<template><section><h2>Mandats et contrats</h2><p>Registre administratif Assurance. Les états de suivi ne constituent pas une signature ni une validation juridique.</p><p v-if="error" role="alert">{{error}}</p><AssuranceContactEditor v-if="selected" :key="selected.id" :contact="selected" role="administrator" :request="request" :portal="portal" @close="selected=null;load()" @changed="load()"/><template v-else><form @submit.prevent="load(true)"><fieldset :disabled="busy"><label>Référence ou nom du prospect<input v-model="filters.search" maxlength="250"></label><label>Type<select v-model="filters.kind"><option value="">Tous</option><option value="mandate">Mandat</option><option value="contract">Contrat</option></select></label><label>État<select v-model="filters.status"><option value="">Tous, y compris archivés</option><option v-for="(label,key) in states" :key="key" :value="key">{{label}}</option></select></label><label>Début à partir du<input v-model="filters.starts_from" type="date"></label><label>Début jusqu’au<input v-model="filters.starts_to" type="date"></label><label>Fin à partir du<input v-model="filters.ends_from" type="date"></label><label>Fin jusqu’au<input v-model="filters.ends_to" type="date"></label><p>Bornes incluses. Un filtre de date exclut les suivis dont cette date n’est pas renseignée.</p><button class="secondary">Rechercher</button><button type="button" class="secondary" @click="clear">Réinitialiser</button></fieldset></form><div class="table-scroll"><table><thead><tr><th>Référence</th><th>Prospect</th><th>Type</th><th>État</th><th>Début</th><th>Fin</th><th>Pièces liées</th><th>Actions</th></tr></thead><tbody><tr v-for="row in rows" :key="row.id"><td>{{row.reference}}</td><td>{{row.contact.name||'Sans nom'}} · réf. {{row.contact.id}}</td><td>{{row.kind==='mandate'?'Mandat':'Contrat'}}</td><td>{{states[row.status]}}</td><td>{{row.starts_on||'Non renseigné'}}</td><td>{{row.ends_on||'Non renseigné'}}</td><td>{{row.document_count}}</td><td><button class="secondary" :disabled="busy" @click="open(row)">Ouvrir la fiche</button></td></tr><tr v-if="!rows.length"><td colspan="8">{{busy?'Chargement…':'Aucun suivi correspondant.'}}</td></tr></tbody></table></div><p>{{count}} suivi(s) · page {{page}} · ordre des dernières modifications</p><button class="secondary" :disabled="busy||page===1" @click="page--;load()">Précédent</button><button class="secondary" :disabled="busy||page*25>=count" @click="page++;load()">Suivant</button><button class="secondary" :disabled="busy" @click="load()">Actualiser</button></template></section></template>
